"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["25974"],{83815(e){e.exports=JSON.parse('{"id":"V4-063","slug":"audit-committee","term":"Audit Committee","also_known_as":[],"difficulty":"Intermediate","definition":"An audit committee is a committee of a company\u2019s board of directors, usually made up of independent directors, responsible for overseeing financial reporting, internal controls, risk management and the relationship with the external auditor.","explanation":["The audit committee provides focused oversight of the integrity of a company\u2019s financial statements. Its typical responsibilities include reviewing the financial statements and key accounting judgments, overseeing internal controls and the internal audit function, recommending the appointment of the external auditor, approving audit fees and non-audit services, reviewing the auditor\u2019s findings and overseeing whistleblowing arrangements.","For example, if management proposes a significant change in how revenue is recognised, the audit committee would review the reasoning, discuss it with the external auditor and challenge management if needed before the accounts are approved.","Rules for listed companies in many countries require audit committees to consist of independent directors, at least one of whom has recent and relevant financial experience. In the United States, these requirements were strengthened by the Sarbanes-Oxley Act.","An effective audit committee helps prevent accounting errors and fraud and increases investor confidence. Its members need financial knowledge, independence from management and enough time to scrutinise complex issues."],"note":"","total":1725,"prev":{"slug":"audit","term":"Audit"},"next":{"slug":"audit-trail","term":"Audit Trail"}}')}}]);